import {stormState,relaySignal,settleRelaySignal,claimRelay,beginRelayRound,relayReward} from './thunderplain-rules.js?v=0.90.52';
export const RELAY_TIMING={watch:1800,catch:1600};
export function relayPhase(elapsed){return elapsed<RELAY_TIMING.watch?'study':elapsed<RELAY_TIMING.watch+RELAY_TIMING.catch?'catch':'done';}
export function stormRelayMenu(a){
 const {state:s,openModal,$,rewardTransaction:commit,closeModal,reducedMotion}=a,q=stormState(s).relay,reward=relayReward(s),names=['Amber','Azure','Ivory'];
 let phase='idle',started=0,timer=null,demoStep=0;
 const clear=()=>{clearInterval(timer);timer=null;};
 openModal('Stormcatch · lightning relay',`<p class="relay-guide"><b>1. LOOK</b> at the lit receiver. <b>2. WAIT</b> while the charge approaches. <b>3. TAP</b> that same receiver when the ring turns green and says <b>TAP NOW</b>.</p><p id="relay-reward">${q.claimed?'Shift complete. Play again for a different supply reward.':`This shift · ${reward.text}.`}</p><div class="storm-relay"><p id="relay-count">${q.caught} / 5 charges · ${q.clears} shifts completed</p><div class="relay-status" id="relay-status">READY</div><div class="relay-track" aria-hidden="true"><div class="relay-target">TAP ZONE</div><span id="relay-orb">●</span></div><div class="relay-receivers">${names.map((n,i)=>`<button data-relay="${i}" aria-label="${n} receiver"><span class="relay-lamp"></span>${n}<small class="relay-tap-hint"></small></button>`).join('')}</div><p id="relay-signal" role="status" aria-live="polite">${q.claimed?'Start another shift whenever you like.':q.caught>=5?'Five charges stored. Collect this shift’s supplies.':'Try the example, or begin your first signal.'}</p><progress id="relay-charge" max="1" value="0" aria-label="Incoming charge"></progress></div><div class="modal-actions"><button id="relay-demo">Watch example · no stakes</button><button id="relay-begin" class="primary" ${q.caught>=5?'hidden':''}>Begin signal</button><button id="relay-claim" ${q.caught<5||q.claimed?'hidden':''}>Collect shift supplies</button><button id="relay-replay" class="primary" ${q.claimed?'':'hidden'}>Play again · new rewards</button></div>`,clear);
 const rods=[...document.querySelectorAll('[data-relay]')];
 const text=(id,t)=>{if($(id).textContent!==t)$(id).textContent=t;};
 const lamps=(which,enabled)=>rods.forEach((b,i)=>{b.disabled=!enabled;b.classList.toggle('lit',i===which);b.querySelector('.relay-tap-hint').textContent='';});lamps(-1,false);
 const display=(kind,which,ratio=0,demo=false)=>{phase=kind;$('#relay-status').classList.toggle('tap-now',kind==='catch');$('.relay-track').classList.toggle('open',kind==='catch');text('#relay-status',(demo?'EXAMPLE · ':'')+(kind==='study'?'WAIT':kind==='catch'?'TAP NOW':'READY'));$('#relay-charge').value=ratio;$('#relay-charge').classList.toggle('charged',kind==='catch');$('#relay-orb').style.left=(4+ratio*88)+'%';text('#relay-signal',kind==='study'?`Remember ${names[which]}. Wait—do not tap yet.`:kind==='catch'?`TAP THE ${names[which].toUpperCase()} RECEIVER NOW`:'Ready for another signal.');if(kind==='catch')rods[which].querySelector('.relay-tap-hint').textContent=demo?'☟ Example tap':'☟ TAP';};
 const endDemo=()=>{clear();phase='idle';lamps(-1,false);$('#relay-demo').textContent='Watch example again';$('#relay-demo').disabled=false;$('#relay-begin').disabled=false;$('#relay-replay').disabled=false;$('#relay-claim').disabled=false;$('#relay-status').classList.remove('tap-now');text('#relay-status','EXAMPLE COMPLETE');text('#relay-signal','The example tapped Amber only after TAP NOW appeared. Your saved charges and rewards have not changed.');};
 const demoCatch=()=>{lamps(0,false);display('catch',0,.72,true);rods[0].classList.add('example-tap');};
 $('#relay-demo').onclick=()=>{
  if(demoStep&&reducedMotion()){if(demoStep===1){demoCatch();demoStep=2;$('#relay-demo').textContent='Finish example';}else{demoStep=0;rods[0].classList.remove('example-tap');endDemo();}return;}
  clear();lamps(0,false);display('study',0,.15,true);$('#relay-begin').disabled=true;$('#relay-replay').disabled=true;$('#relay-claim').disabled=true;
  if(reducedMotion()){demoStep=1;$('#relay-demo').textContent='Show when to tap';return;}
  $('#relay-demo').disabled=true;started=performance.now();timer=setInterval(()=>{const elapsed=performance.now()-started;if(elapsed<RELAY_TIMING.watch)display('study',0,elapsed/(RELAY_TIMING.watch+RELAY_TIMING.catch),true);else if(elapsed<RELAY_TIMING.watch+850)demoCatch();else{rods[0].classList.remove('example-tap');endDemo();}},50);
 };
 const finish=rod=>{clear();const correct=rod>=0&&rod===relaySignal(q)&&phase==='catch';if(!commit(()=>settleRelaySignal(s,rod,correct))){phase='idle';$('#relay-begin').hidden=false;$('#relay-demo').disabled=false;return;}phase='idle';lamps(-1,false);$('#relay-status').classList.remove('tap-now');text('#relay-status',correct?'CHARGE STORED':'SAFE DISCHARGE');text('#relay-signal',correct?'Good timing. The next signal is ready.':'Wait for TAP NOW, then tap the receiver you remembered. Try again.');text('#relay-count',`${q.caught} / 5 charges · ${q.clears} shifts completed`);$('#relay-begin').hidden=q.caught>=5;$('#relay-begin').textContent='Next signal';$('#relay-demo').disabled=false;$('#relay-claim').hidden=q.caught<5||q.claimed;};
 $('#relay-begin').onclick=()=>{if(timer||demoStep)return;const which=relaySignal(q);lamps(which,true);$('#relay-begin').hidden=true;$('#relay-demo').disabled=true;started=performance.now();if(reducedMotion()){display('catch',which,.75);text('#relay-signal',`Reduced motion · tap ${names[which]} when ready. No timer.`);return;}
  const tick=()=>{const elapsed=performance.now()-started,kind=relayPhase(elapsed);if(kind==='done'){finish(-1);return;}display(kind,which,elapsed/(RELAY_TIMING.watch+RELAY_TIMING.catch));};tick();timer=setInterval(tick,50);
 };
 rods.forEach((b,i)=>b.onclick=()=>{if(phase==='study'||phase==='catch')finish(i);});
 $('#relay-claim').onclick=()=>{if(q.caught<5||q.claimed)return;const earned=relayReward(s);if(!commit(()=>claimRelay(s)))return;closeModal();a.showDialogue([a.line('Relay keeper Samira',`Five charges stored. Take ${earned.text}. There is always another shift if you want one; the next supply crate will be different.`,'REV-MARYAM')]);};
 $('#relay-replay').onclick=()=>{if(!q.claimed||!commit(()=>beginRelayRound(s)))return;clear();stormRelayMenu(a);};
}
